@if($unit==='garden')<script>(()=>{const form=document.getElementById('unitForm'),type=form?.querySelector('[name="record_type"]'),quantity=form?.querySelector('[name="quantity"]'),unit=form?.querySelector('[name="measure_unit"]'),amount=form?.querySelector('[name="amount"]'),status=form?.querySelector('[name="status"]');if(!form||!type)return;const help=document.createElement('p');help.className='notice';help.textContent='Enter only the crop and amount collected. You do not need to know its money value; management or Finance will value it later.';form.querySelector('h3')?.after(help);const sync=()=>{const harvest=type.value==='harvest';help.hidden=!harvest;amount.closest('.field').hidden=harvest;amount.disabled=harvest;status.closest('.field').hidden=harvest;if(harvest)status.value='recorded';quantity.required=harvest;unit.required=harvest;form.querySelector('h3').textContent=harvest?'Record today’s harvest':'Add Garden Unit activity'};type.addEventListener('change',sync);sync()})()</script>@endif
